	/** 
	 * jumpstart the process by instantiating2 Merchant
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		merchantId = MerchantService.getMerchantInstance()
		.createMerchant( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		MerchantService.getMerchantInstance()
				.createMerchant( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.merchantSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Merchant : " + successValue.getMerchantId());
							  if (successValue.getMerchantId().equals(merchantId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfMerchantList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Merchant test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on merchant consumed")
					);
			subscriber.merchantSubscribe( merchantId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Merchant : " + successValue.getMerchantId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfMerchantList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on merchant for merchantId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Merchant. 
	 */
	protected Merchant read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Merchant" );

		Merchant entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Merchant with primary key" );
		msg.append( merchantId );
		
		MerchantFetchOneSummary fetchOneSummary = new MerchantFetchOneSummary( merchantId );

		try {
			entity = MerchantService.getMerchantInstance().getMerchant( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Merchant " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Merchant.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Merchant." );

		StringBuilder msg = new StringBuilder( "Failed to update a Merchant : " );        
		Merchant entity = read();
		UpdateMerchantCommand command = generateUpdateCommand();
		command.setMerchantId(entity.getMerchantId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Merchant." );

			// for use later on...
			merchantId = entity.getMerchantId();

			MerchantService proxy = MerchantService.getMerchantInstance();  

			proxy.updateMerchant( command ).get();

			LOGGER.info( "-- Successfully saved Merchant - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + merchantId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Merchant.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Merchant." );

		Merchant entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Merchant with id " + merchantId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Merchant with id " + merchantId );

			throw e;
		}

		try{
			MerchantService.getMerchantInstance().delete( new DeleteMerchantCommand( entity.getMerchantId() ) ).get();
			LOGGER.info( "-- Successfully deleted Merchant with id " + merchantId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Merchant with id " + merchantId );

			throw e;
		}
	}

	/**
	 * get all Merchants.
	 */
	protected List<Merchant> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Merchants:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Merchant : " );        
		List<Merchant> collection  = new ArrayList<>();

		try {
			// call the static get method on the MerchantService
			collection = MerchantService.getMerchantInstance().getAllMerchant();
			assertNotNull( collection, "An Empty collection of Merchant was incorrectly returned.");
			
			// Now print out the values
			Merchant entity = null;            
			Iterator<Merchant> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getMerchantId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

